import * as React from 'react';
import FishYearCatchComments from './FishYearCatchComments';
import FishIllustration from './FishIllustration';
import ImageLightbox from './ImageLightbox';
import Photo from './Photo';
import LikeButton from './LikeButton';
import PostMenu from './PostMenu';
import speciesIcon from '../utils/speciesOptions';

type Catch = { id: string; user_id: string; angler_name: string; angler_avatar_url?: string; month: string; species: string; caught_at: string | null; photo_url: string };
const months = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];

// Groups a month's catches by angler (preserving first-appearance order) so a crew member
// who logged several fish in the same month shows up as one bulked entry rather than
// crowding the board with a card per catch.
function groupByAngler(entries: Catch[]) {
  const groups: Record<string, Catch[]> = {};
  const order: string[] = [];
  for (const entry of entries) {
    if (!groups[entry.user_id]) { groups[entry.user_id] = []; order.push(entry.user_id); }
    groups[entry.user_id].push(entry);
  }
  return order.map((userId) => groups[userId]);
}

function MonthDetail({ entries, currentUserId, onDelete, highlightId, highlightCommentId }: { entries: Catch[]; currentUserId?: string; onDelete: (id: string) => void; highlightId?: string | null; highlightCommentId?: string | null }) {
  const groups = React.useMemo(() => groupByAngler(entries), [entries]);
  if (!entries.length) return <div className="empty-state"><FishIllustration species="smallmouth" className="empty-state-sticker" /><p className="month-empty">No catches yet. Somebody's gotta break the ice.</p></div>;
  return <div className="month-catches">{groups.map((group) => group.length === 1
    ? <MonthCatch key={group[0].id} entry={group[0]} currentUserId={currentUserId} onDelete={onDelete} highlighted={group[0].id === highlightId} highlightCommentId={group[0].id === highlightId ? highlightCommentId : null} />
    : <MonthCatchGroup key={group[0].user_id} entries={group} currentUserId={currentUserId} onDelete={onDelete} highlightId={highlightId} highlightCommentId={highlightCommentId} />)}</div>;
}

function MonthCatchGroup({ entries, currentUserId, onDelete, highlightId, highlightCommentId }: { entries: Catch[]; currentUserId?: string; onDelete: (id: string) => void; highlightId?: string | null; highlightCommentId?: string | null }) {
  const containsHighlight = highlightId ? entries.some((entry) => entry.id === highlightId) : false;
  const [open, setOpen] = React.useState(containsHighlight);
  React.useEffect(() => { if (containsHighlight) setOpen(true); }, [containsHighlight]);
  const [first] = entries;
  return <div className="catch-card catch-card-group">
    <button type="button" className="catch-card-group-header" onClick={() => setOpen((value) => !value)} aria-expanded={open}>
      <span className="mini-avatar">{first.angler_avatar_url ? <Photo src={first.angler_avatar_url} alt="" fallback={first.angler_name.slice(0, 1)} /> : first.angler_name.slice(0, 1)}</span>
      <div><strong>{first.angler_name}</strong><span className="catch-card-group-meta">{entries.length} fish logged this month</span></div>
      <span className="expand-icon">{open ? '−' : '+'}</span>
    </button>
    {open && <div className="catch-card-group-detail reveal-in">
      {entries.map((entry) => <MonthCatch key={entry.id} entry={entry} currentUserId={currentUserId} onDelete={onDelete} highlighted={entry.id === highlightId} highlightCommentId={entry.id === highlightId ? highlightCommentId : null} />)}
    </div>}
  </div>;
}

function MonthCatch({ entry, currentUserId, onDelete, highlighted, highlightCommentId }: { entry: Catch; currentUserId?: string; onDelete: (id: string) => void; highlighted?: boolean; highlightCommentId?: string | null }) {
  const [imageOpen, setImageOpen] = React.useState(false);
  const ref = React.useRef<HTMLDivElement>(null);
  React.useEffect(() => {
    if (highlighted) ref.current?.scrollIntoView({ behavior: 'smooth', block: 'center' });
  }, [highlighted]);
  return <div className={`catch-card ${highlighted ? 'is-shared-highlight' : ''}`} ref={ref}>
    <PostMenu
      shareData={{ title: `${entry.angler_name}'s ${entry.species}`, text: `${entry.angler_name} caught a ${entry.species}${entry.caught_at ? ` on ${entry.caught_at}` : ''} — Fish Year 2026.`, url: `${window.location.origin}/fish-year?catch=${entry.id}` }}
      onDelete={currentUserId && entry.user_id === currentUserId ? () => onDelete(entry.id) : undefined}
    />
    <button className="catch-card-media" type="button" onClick={() => entry.photo_url && setImageOpen(true)} aria-label={entry.photo_url ? `Expand ${entry.angler_name}'s catch photo` : `${entry.angler_name} caught a ${entry.species}, no photo yet`}>
      {entry.photo_url ? <Photo src={entry.photo_url} alt={`${entry.angler_name}'s ${entry.species}`} fallback={<span className="catch-card-placeholder"><FishIllustration species={speciesIcon(entry.species)} /></span>} /> : <span className="catch-card-placeholder"><FishIllustration species={speciesIcon(entry.species)} /></span>}
      <span className="catch-card-species">{entry.species}</span>
    </button>
    <div className="catch-card-caption">
      <span className="mini-avatar">{entry.angler_avatar_url ? <Photo src={entry.angler_avatar_url} alt="" fallback={entry.angler_name.slice(0, 1)} /> : entry.angler_name.slice(0, 1)}</span>
      <div><strong>{entry.angler_name}</strong><span>{entry.caught_at || ''}</span></div>
    </div>
    <div className="catch-card-actions">
      <LikeButton targetType="fish_year_catch" targetId={entry.id} ownerId={entry.user_id} />
      <FishYearCatchComments catchId={entry.id} ownerId={entry.user_id} defaultOpen={highlighted} highlightCommentId={highlightCommentId} />
    </div>
    {imageOpen && <ImageLightbox src={entry.photo_url} alt={`${entry.angler_name}'s expanded ${entry.species}`} label={`${entry.angler_name}'s catch photo`} onClose={() => setImageOpen(false)} />}
  </div>;
}

function MonthCard({ month, index, entries, currentUserId, onDelete, highlightId, highlightCommentId }: { month: string; index: number; entries: Catch[]; currentUserId?: string; onDelete: (id: string) => void; highlightId?: string | null; highlightCommentId?: string | null }) {
  const containsHighlight = highlightId ? entries.some((entry) => entry.id === highlightId) : false;
  const [open, setOpen] = React.useState(index < 2 || containsHighlight);
  return <div className={`month-card ${entries.length ? 'has-catches' : ''} ${open ? 'is-open' : ''}`}><button className="month-card-header" type="button" onClick={() => setOpen(!open)} aria-expanded={open}><span className="month-number">{String(index + 1).padStart(2, '0')}</span><span className="month-name"><strong>{month}</strong><small>{entries.length ? `${entries.length} catches logged` : 'Waiting for a catch'}</small></span><span className={`month-state ${entries.length ? 'complete' : ''}`}>{entries.length ? '✓' : '—'}</span><span className="expand-icon">{open ? '−' : '+'}</span></button>{open && <div className="month-card-detail reveal-in"><MonthDetail entries={entries} currentUserId={currentUserId} onDelete={onDelete} highlightId={highlightId} highlightCommentId={highlightCommentId} /></div>}</div>;
}

export default function Participants({ catches, currentUserId, onDelete, highlightId, highlightCommentId }: { catches: Catch[]; currentUserId?: string; onDelete: (id: string) => void; highlightId?: string | null; highlightCommentId?: string | null }) {
  const entries = React.useMemo(() => {
    const grouped: Record<string, Catch[]> = {};
    for (const entry of catches) grouped[entry.month] = [...(grouped[entry.month] || []), entry];
    return grouped;
  }, [catches]);
  const currentParticipants = Array.from(new Set(catches.map((entry) => entry.angler_name)));
  return <div className="participants-panel"><div className="participant-summary"><div><strong>{currentParticipants.length}</strong><span>active anglers</span></div><div><strong>{Object.values(entries).filter((monthEntries) => monthEntries.length).length.toString().padStart(2, '0')}</strong><span>months complete</span></div><div><strong>{12 - Object.values(entries).filter((monthEntries) => monthEntries.length).length}</strong><span>months ahead</span></div></div><div className="progress-board"><div className="progress-board-heading"><span className="eyebrow">MONTH-BY-MONTH</span><span className="muted-label">Tap a month to inspect catches</span></div><div className="months-grid">{months.map((month, index) => <MonthCard key={month} month={month} index={index} entries={entries[month] || []} currentUserId={currentUserId} onDelete={onDelete} highlightId={highlightId} highlightCommentId={highlightCommentId} />)}</div></div></div>;
}
